:\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"eael_image_masking_custom_clip_path_hover\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\"},\"elements\":[{\"id\":\"44876064\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"https:\\/\\/qmbqbrt0dq.wpdns.site\\/wp-content\\/uploads\\/2026\\/01\\/Construction-Management-1.webp\",\"id\":210,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"object-fit\":\"cover\",\"eael_image_masking_custom_clip_path\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"eael_image_masking_custom_clip_path_hover\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\"},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":true},{\"id\":\"435c36b7\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"},\"padding\":{\"unit\":\"px\",\"top\":0,\"right\":0,\"bottom\":0,\"left\":0,\"isLinked\":true},\"flex_gap\":{\"unit\":\"px\",\"size\":0,\"column\":\"0\",\"row\":\"0\"},\"eael_image_masking_custom_clip_path\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"eael_image_masking_custom_clip_path_hover\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\"},\"elements\":[{\"id\":\"79629cc0\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"box_shadow_box_shadow_type\":\"yes\",\"box_shadow_box_shadow\":{\"horizontal\":5,\"vertical\":5,\"blur\":10,\"spread\":0,\"color\":\"rgba(0,0,0,0.5)\"},\"eael_image_masking_custom_clip_path\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"eael_image_masking_custom_clip_path_hover\