adquarters\",\"header_size\":\"h1\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":50,\"sizes\":[]},\"typography_font_weight\":\"600\",\"eael_vto_writing_gradient_color_repeater\":[{\"eael_vto_writing_gradient_color\":\"#7C62FF\",\"eael_vto_writing_gradient_color_location\":{\"unit\":\"%\",\"size\":50},\"_id\":\"ee6243b\"},{\"eael_vto_writing_gradient_color\":\"#FF6464\",\"eael_vto_writing_gradient_color_location\":{\"unit\":\"%\",\"size\":90},\"_id\":\"e7455cc\"}],\"_flex_align_self\":\"flex-start\",\"eael_image_masking_custom_clip_path\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"eael_image_masking_custom_clip_path_hover\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"_animation\":\"fadeInLeft\",\"__globals__\":{\"title_color\":\"globals\\/colors?id=1eaf522\"}},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":false},{\"id\":\"59f5e4bd\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"flex_align_items\":\"center\",\"padding\":{\"unit\":\"px\",\"top\":\"40\",\"right\":\"40\",\"bottom\":\"40\",\"left\":\"40\",\"isLinked\":true},\"eael_image_masking_custom_clip_path\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"eael_image_masking_custom_clip_path_hover\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\"},\"elements\":[{\"id\":\"64007d02\",\"elType\":\"container\",\"settings\":{\"container_type\":\"grid\",\"presetTitle\":\"Grid\",\"presetIcon\":\"eicon-container-grid\",\"content_width\":\"full\",\"grid_columns_grid\":{\"unit\":\"fr\",\"size\":2,\"sizes\":[]},\"grid_rows_grid\":{\"unit\":\"fr\",\"size\":1,\"sizes\":[]},\"eael_image_masking_custom_clip_path\"