>\n\n<!-- wp:group {\"metadata\":{\"blockVisibility\":false},\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|40\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:embed {\"url\":\"https://www.youtube.com/watch?v=vbZgiwBxDbE\",\"type\":\"video\",\"providerNameSlug\":\"youtube\",\"responsive\":true,\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://www.youtube.com/watch?v=vbZgiwBxDbE\n</div></figure>\n<!-- /wp:embed -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"spacing\":{\"margin\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"0\",\"bottom\":\"0\"}},\"border\":{\"radius\":{\"topLeft\":\"0px\",\"topRight\":\"0px\",\"bottomLeft\":\"0px\",\"bottomRight\":\"0px\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"xx-large\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-contrast-color has-text-color has-link-color has-xx-large-font-size\" style=\"border-top-left-radius:0px;border-top-right-radius:0px;border-bottom-left-radius:0px;border-bottom-right-radius:0px;margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\">Tell your story</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"metadata\":{\"categories\":[\"header\"],\"patternName\":\"twentytwentyfive/header-columns\",\"name\":\"Header with columns\"},\"layout\":{\"type\":\"grid\"}} -->\n<div class=\"wp-block-group\"></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Like flowers that bloom in unexpected places, every story unfolds with beauty and resilience, revealing hidden wonders.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Learn more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":{\"top\":\"0\",\"left\":\"var:preset|spacing|70\"}}}} -->\n<div class=\"wp-block-columns\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#060ef6\"}}},\"color\":{\"text\":\"#060ef6\"}},\"fontSize\":\"xx-large\"} -->\n<p class=\"has-text-color has-link-color has-xx-large-font-size\" style=\"color:#060ef6\"><strong>150</strong><strong>+</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>years in business</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#0008ff\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#0008ff\"}}}},\"fontSize\":\"xx-large\"} -->\n<p class=\"has-text-color has-link-color has-xx-large-font-size\" style=\"color:#0008ff\"><strong>20</strong><strong>+</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>countries globally where we’ve worked</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#0003ff\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#0003ff\"}}}},\"fontSize\":\"xx-large\"} -->\n<p class=\"has-text-color has-link-color has-xx-large-font-size\" style=\"color: