(604,2,'2026-02-05 17:49:57','2026-02-05 17:49:57','/* ============================================\n   SPD - CSS para pegar en WordPress\n   Apariencia → Personalizar → CSS adicional\n   Todo está dentro de .spd-homepage para no afectar el resto del sitio\n   ============================================ */\n\n.spd-homepage {\n  --color-dark: #0d1b2a;\n  --color-dark-blue: #1b263b;\n  --color-navy: #1e3a5f;\n  --color-accent: #e07c24;\n  --color-accent-hover: #c96a1a;\n  --color-white: #ffffff;\n  --color-gray: #4a5568;\n  --color-gray-light: #718096;\n  --font-sans: \'Inter\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', sans-serif;\n  --container-max: 1200px;\n  --header-height: 72px;\n  font-family: var(--font-sans);\n  font-size: 16px;\n  line-height: 1.6;\n  color: var(--color-dark);\n  margin: 0;\n}\n\n.spd-homepage *,\n.spd-homepage *::before,\n.spd-homepage *::after {\n  box-sizing: border-box;\n}\n\n.spd-homepage a {\n  color: inherit;\n  text-decoration: none;\n}\n\n.spd-homepage ul {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n.spd-homepage .container {\n  max-width: var(--container-max);\n  margin: 0 auto;\n  padding: 0 24px;\n}\n\n/* Header */\n.spd-homepage .site-header {\n  position: fixed;\n  top: 0;\n  left: 0;\n  right: 0;\n  height: var(--header-height);\n  background: var(--color-dark);\n  z-index: 9999;\n  display: flex;\n  align-items: center;\n}\n\n.spd-homepage .header-inner {\n  width: 100%;\n  max-width: var(--container-max);\n  margin: 0 auto;\n  padding: 0 24px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.spd-homepage .logo {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  color: var(--color-white);\n  font-weight: 700;\n  font-size: 1.1rem;\n}\n\n.spd-homepage .logo-icon {\n  width: 36px;\n  height: 36px;\n  background: rgba(255, 255, 255, 0.2);\n  display: block;\n  border-radius: 4px;\n  background-image: linear-gradient(to right, rgba(255,255,255,0.3) 1px, transparent 1px),\n    linear-gradient(to bottom, rgba(255,255,255,0.3) 1px, transparent 1px);\n  background-size: 12px 12px;\n}\n\n.spd-homepage .main-nav ul {\n  display: flex;\n  align-items: center;\n  gap: 28px;\n}\n\n.spd-homepage .main-nav a {\n  color: var(--color-white);\n  font-weight: 500;\n  font-size: 0.95rem;\n}\n\n.spd-homepage .main-nav a:hover {\n  color: var(--color-accent);\n}\n\n.spd-homepage .chevron {\n  font-size: 0.65em;\n  opacity: 0.8;\n}\n\n/* Botones */\n.spd-homepage .btn {\n  display: inline-block;\n  padding: 14px 28px;\n  font-family: var(--font-sans);\n  font-weight: 600;\n  font-size: 0.9rem;\n  letter-spacing: 0.02em;\n  border: none;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: background 0.2s, transform 0.15s;\n}\n\n.spd-homepage .btn:hover {\n  transform: translateY(-1px);\n}\n\n.spd-homepage .btn-primary {\n  background: var(--color-accent);\n  color: var(--color-white);\n}\n\n.spd-homepage .btn-primary:hover {\n  background: var(--color-accent-hover);\n}\n\n.spd-homepage .btn-dark {\n  background: var(--color-navy);\n  color: var(--color-white);\n}\n\n.spd-homepage .btn-dark:hover {\n  background: var(--color-dark-blue);\n}\n\n/* Hero */\n.spd-homepage .hero {\n  position: relative;\n  min-height: 100vh;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: var(--color-navy) url(\'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=1920\') center/cover no-repeat;\n  margin-top: var(--header-height);\n}\n\n.spd-homepage .hero-overlay {\n  position: absolute;\n  inset: 0;\n  background: rgba(27, 38, 59, 0.75);\n}\n\n.spd-homepage .hero-content {\n  position: relative;\n  z-index: 1;\n  text-align: center;\n  padding: 40px 24px;\n}\n\n.spd-homepage .hero-title {\n  margin: 0 0 8px;\n  font-size: clamp(2.5rem, 6vw, 4rem);\n  font-weight: 700;\n  color: var(--color-white);\n  letter-spacing: -0.02em;\n}\n\n.spd-homepage .hero-subtitle {\n  margin: 0 0 40px;\n  font-size: clamp(1.25rem, 3vw, 1.75rem);\n  font-weight: 500;\n  color: var(--color-white);\n  opacity: 0.95;\n}\n\n.spd-homepage .hero-buttons {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 16px;\n  justify-content: center;\n}\n\n.spd-homepage .section-label {\n  font-size: 0.85rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--color-gray);\n  margin: 0 0 16px;\n}\n\n/* Approach & Expertise */\n.spd-homepage .approach {\n  padding: 80px 0 100px;\n  background: var(--color-white);\n}\n\n.spd-homepage .approach-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 48px;\n  align-items: start;\n  margin-bottom: 56px;\n}\n\n@media (max-width: 768px) {\n  .spd-homepage .approach-grid {\n    grid-template-columns: 1fr;\n  }\n}\n\n.spd-homepage .approach-headline h3 {\n  margin: 0;\n  font-size: clamp(1.5rem, 3vw, 2rem);\n  font-weight: 700;\n  color: var(--color-navy);\n  line-height: 1.3;\n}\n\n.spd-homepage .approach-text p {\n  margin: 0;\n  font-size: 1rem;\n  color: var(--color-gray);\n  line-height: 1.7;\n}\n\n.spd-homepage .metrics {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 32px;\n  margin-bottom: 64px;\n  text-align: center;\n}\n\n@media (max-width: 600px) {\n  .spd-homepage .metrics {\n    grid-template-columns: 1fr;\n  }\n}\n\n.spd-homepage .metric-number {\n  display: block;\n  font-size: clamp(2.5rem, 5vw, 3.5rem);\n  font-weight: 700;\n  color: var(--color-navy);\n  margin-bottom: 8px;\n}\n\n.spd-homepage .metric-label {\n  font-size: 0.9rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--color-dark);\n}\n\n.spd-homepage .partner-logos {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: center;\n  gap: 40px;\n  padding-top: 24px;\n  border-top: 1px solid #e2e8f0;\n}\n\n.spd-homepage .partner-logo {\n  font-size: 1rem;\n  font-weight: 700;\n  color: var(--color-gray-light);\n  padding: 12px 20px;\n  background: #f7fafc;\n  border-radius: 6px;\n}\n\n/* Featured Projects */\n.spd-homepage .featured-projects {\n  padding: 80px 0 100px;\n  background: var(--color-accent);\n}\n\n.spd-homepage .featured-projects .section-label {\n  color: var(--color-gray);\n}\n\n.spd-homepage .projects-intro {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 32px;\n  margin-bottom: 48px;\n}\n\n.spd-homepage .projects-text-box {\n  flex: 1;\n  min-width: 280px;\n  max-width: 640px;\n  background: var(--color-white);\n  padding: 40px;\n  border-radius: 12px;\n  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);\n}\n\n.spd-homepage .projects-title {\n  margin: 0 0 16px;\n  font-size: clamp(1.5rem, 2.5vw, 2rem);\n  font-weight: 700;\n  color: var(--color-dark);\n}\n\n.spd-homepage .projects-text-box p {\n  margin: 0 0 12px;\n  font-size: 0.95rem;\n  color: var(--color-gray);\n}\n\n.spd-homepage .projects-text-box p:last-of-type {\n  margin-bottom: 0;\n}\n\n.spd-homepage .projects-intro .btn-dark {\n  align-self: center;\n}\n\n.spd-homepage .projects-carousel {\n  position: relative;\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n\n.spd-homepage .carousel-arrow {\n  flex-shrink: 0;\n  width: 48px;\n  height: 48px;\n  border-radius: 50%;\n  background: rgba(255, 255, 255, 0.3);\n  color: var(--color-white);\n  border: none;\n  font-size: 1.5rem;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: background 0.2s;\n}\n\n.spd-homepage .carousel-arrow:hover {\n  background: rgba(255, 255, 255, 0.5);\n}\n\n.spd-homepage .projects-cards {\n  display: flex;\n  gap: 24px;\n  flex: 1;\n  min-width: 0;\n  overflow-x: auto;\n  scroll-snap-type: x mandatory;\n  padding-bottom: 8px;\n  scrollbar-width: thin;\n}\n\n.spd-homepage .projects-cards::-webkit-scrollbar {\n  height: 6px;\n}\n\n.spd-homepage .projects-cards::-webkit-scrollbar-thumb {\n  background: rgba(255, 255, 255, 0.4);\n  border-radius: 3px;\n}\n\n@media (max-width: 900px) {\n  .spd-homepage .project-card {\n    min-width: 280px;\n    scroll-snap-align: start;\n  }\n}\n\n.spd-homepage .project-card {\n  flex: 0 0 min(320px, 100%);\n  background: rgba(255, 255, 255, 0.95);\n  border-radius: 12px;\n  overflow: hidden;\n  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);\n  scroll-snap-align: start;\n}\n\n.spd-homepage .project-image {\n  aspect-ratio: 4/3;\n  background: linear-gradient(135deg, #e2e8f0 0%, #cbd5e0 100%);\n}\n\n.spd-homepage .project-caption {\n  padding: 20px;\n}\n\n.spd-homepage .project-category {\n  display: block;\n  font-size: 0.8rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--color-gray-light);\n  margin-bottom: 8px;\n}\n\n.spd-homepage .project-caption h4 {\n  margin: 0;\n  font-size: 1rem;\n  font-weight: 600;\n  color: var(--color-dark);\n  line-height: 1.4;\n}\n\n/* Services */\n.spd-homepage .services {\n  padding: 80px 0 100px;\n  background: var(--color-white);\n}\n\n.spd-homepage .services-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 48px;\n  align-items: start;\n}\n\n@media (max-width: 768px) {\n  .spd-homepage .services-grid {\n    grid-template-columns: 1fr;\n  }\n}\n\n.spd-homepage .services-intro p {\n  margin: 0 0 24px;\n  font-size: 1rem;\n  color: var(--color-gray);\n  line-height: 1.7;\n}\n\n.spd-homepage .services-intro .btn {\n  margin-top: 8px;\n}\n\n.spd-homepage .service-image {\n  aspect-ratio: 16/10;\n  background: linear-gradient(135deg, #e2e8f0 0%, #cbd5e0 100%);\n  border-radius: 12px;\n  margin-bottom: 20px;\n}\n\n.spd-homepage .service-feature h3 {\n  margin: 0 0 12px;\n  font-size: 1.5rem;\n  font-weight: 700;\n  color: var(--color-navy);\n}\n\n.spd-homepage .service-feature p {\n  margin: 0;\n  font-size: 0.95rem;\n  color: var(--color-gray);\n  line-height: 1.6;\n}\n\n/* CTA */\n.spd-homepage .cta-section {\n  position: relative;\n  min-height: 400px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: var(--color-navy) url(\'https://images.unsplash.com/photo-1504307651254-35680f356dfd?w=1920\') center/cover no-repeat;\n}\n\n.spd-homepage .cta-overlay {\n  position: absolute;\n  inset: 0;\n  background: rgba(27, 38, 59, 0.8);\n}\n\n.spd-homepage .cta-content {\n  position: relative;\n  z-index: 1;\n  text-align: center;\n  padding: 60px 24px;\n}\n\n.spd-homepage .cta-text {\n  margin: 0 0 28px;\n  font-size: clamp(1.25rem, 3vw, 1.75rem);\n  font-weight: 600;\n  color: var(--color-white);\n  max-width: 640px;\n  margin-left: auto;\n  margin-right: auto;\n}\n\n/* Footer */\n.spd-homepage .site-footer {\n  background: var(--color-dark-blue);\n  color: var(--color-white);\n  padding: 48px 0 32px;\n}\n\n.spd-homepage .footer-top {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 24px;\n  margin-bottom: 32px;\n  padding-bottom: 24px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.15);\n}\n\n.spd-homepage .footer-top .logo-text {\n  font-weight: 700;\n  font-size: 1.1rem;\n}\n\n.spd-homepage .footer-nav {\n  display: flex;\n  gap: 24px;\n}\n\n.spd-homepage .footer-nav a {\n  color: var(--color-white);\n  font-weight: 500;\n  font-size: 0.95rem;\n}\n\n.spd-homepage .footer-nav a:hover {\n  color: var(--color-accent);\n}\n\n.spd-homepage .footer-bottom {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n}\n\n.spd-homepage .copyright {\n  margin: 0;\n  font-size: 0.9rem;\n  opacity: 0.9;\n}\n\n.spd-homepage .footer-contact {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 20px;\n  font-size: 0.9rem;\n  opacity: 0.9;\n}\n\n.spd-homepage .footer-contact a {\n  color: var(--color-white);\n}\n\n.spd-homepage .footer-contact a:hover {\n  color: var(--color-accent);\n}\n\n@media (max-width: 600px) {\n  .spd-homepage .footer-bottom {\n    flex-direction: column;\n    align-items: flex-start;\n  }\n\n  .spd-homepage .footer-contact {\n    flex-direction: column;\n    align-items: flex-start;\n  }\n}\n','hello-elementor','','publish','closed','closed','','hello-elementor','','','2026-02-08 20:07:56','2026-02-08 20:07:56','',0,'https://qmbqbrt0dq.wpdns.site/2026/02/05/hello-elementor/',0,'custom_css','',0),
