center;\n  justify-content: center;\n  background: var(--color-navy) url(\'https://images.unsplash.com/photo-1504307651254-35680f356dfd?w=1920\') center/cover no-repeat;\n}\n\n.spd-homepage .cta-overlay {\n  position: absolute;\n  inset: 0;\n  background: rgba(27, 38, 59, 0.8);\n}\n\n.spd-homepage .cta-content {\n  position: relative;\n  z-index: 1;\n  text-align: center;\n  padding: 60px 24px;\n}\n\n.spd-homepage .cta-text {\n  margin: 0 0 28px;\n  font-size: clamp(1.25rem, 3vw, 1.75rem);\n  font-weight: 600;\n  color: var(--color-white);\n  max-width: 640px;\n  margin-left: auto;\n  margin-right: auto;\n}\n\n/* Footer */\n.spd-homepage .site-footer {\n  background: var(--color-dark-blue);\n  color: var(--color-white);\n  padding: 48px 0 32px;\n}\n\n.spd-homepage .footer-top {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 24px;\n  margin-bottom: 32px;\n  padding-bottom: 24px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.15);\n}\n\n.spd-homepage .footer-top .logo-text {\n  font-weight: 700;\n  font-size: 1.1rem;\n}\n\n.spd-homepage .footer-nav {\n  display: flex;\n  gap: 24px;\n}\n\n.spd-homepage .footer-nav a {\n  color: var(--color-white);\n  font-weight: 500;\n  font-size: 0.95rem;\n}\n\n.spd-homepage .footer-nav a:hover {\n  color: var(--color-accent);\n}\n\n.spd-homepage .footer-bottom {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n}\n\n.spd-homepage .copyright {\n  margin: 0;\n  font-size: 0.9rem;\n  opacity: 0.9;\n}\n\n.spd-homepage .footer-contact {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 20px;\n  font-size: 0.9rem;\n  opacity: 0.9;\n}\n\n.spd-homepage .footer-contact a {\n  color: var(--color-white);\n}\n\n.spd-homepage .footer-contact a:hover {\n  color: var(--color-accent);\n}\n\n@media (max-width: 600px) {\n  .spd-homepage .footer-bottom {\n    flex-direction: column;\n    align-items: flex-start;\n  }\n\n  .spd-homepage .footer-contact {\n    flex-direction: column;\n    align-items: flex-start;\n  }\n}\n\n.klk{\n	color:red;\n}\n','hello-elementor','','inherit','closed','closed','','604-revision-v1','','','2026-02-08 19:57:40','2026-02-08 19:57:40','',604,'https://qmbqbrt0dq.wpdns.site/?p=630',0,'revision','',0),
(631,2,'2026-02-08 19:59:56','2026-02-08 19:59:56','<!-- wp:group {\"metadata\":{\"categories\":[\"call-to-action\"],\"patternName\":\"twentytwentyfive/event-rsvp\",\"name\":\"Event RSVP\"},\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0\"><!-- wp:columns {\"isStackedOnMobile\":false,\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|80\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-columns alignfull is-not-stacked-on-mobile\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--80);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:column {\"width\":\"66.66%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:66.66%\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|20\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"fontSize\":\"xx-large\"} -->\n<h2 class=\"wp-block-heading has-xx-large-font-size\">\n					“Stories, <span lang=\"es\">historias</span>, <span lang=\"uk\">iсторії</span>, <span lang=\"el\">iστορίες</span>”				</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"x-large\"} -->\n<p class=\"has-x-large-font-size\">Mon, Jan 1</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"0px\",\"style\":{\"layout\":{\"selfStretch\":\"fixed\",\"flexSize\":\"140px\"}}} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<h2 class=\"klk\">klk</h2>\n<!-- /wp:html --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"12vw\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:12vw\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"left\",\"style\":{\"typography\":{\"writingMode\":\"vertical-rl\",\"textTransform\":\"uppercase\",\"lineHeight\":\"0.6\"}}} -->\n<p class=\"has-text-align-left\" style=\"line-height:0.6;text-transform:uppercase;writing-mode:vertical-rl\">Free Workshop</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"align\":\"full\",\"className\":\"is-style-section-2\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"0\",\"left\":\"0\"},\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-columns alignfull is-style-section-2\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|20\",\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"}},\"dimensions\":{\"minHeight\":\"33vh\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\",\"verticalAlignment\":\"space-between\"}} -->\n<div class=\"wp-block-group\" style=\"min-height:33vh;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:paragraph -->\n<p>This immersive event celebrates the universal human experience through the lenses of history and ancestry, featuring a diverse array of photographers whose works capture the essence of different cultures and historical moments.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"0px\",\"style\":{\"layout\":{\"flexSize\":\"100px\",\"selfStretch\":\"fixed\"}}} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"fontSize\":\"xx-large\"} -->\n<h2 class=\"wp-block-heading has-xx-large-font-size\"><a href=\"#\">RSVP</a></h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:cover {\"url\":\"https://qmbqbrt0dq.wpdns.site/wp-content/themes/twentytwentyfive/assets/images/botany-flowers-closeup.webp\",\"alt\":\"Close up photo of white flowers on a grey background\",\"dimRatio\":0,\"isDark\":false} -->\n<div class=\"wp-block-cover is-light\"><img class=\"wp-block-cover__image-background\" alt=\"Close up photo of white flowers on a grey background\" src=\"https://qmbqbrt0dq.wpdns.site/wp-content/themes/twentytwentyfive/assets/images/botany-flowers-closeup.webp\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:spacer {\"height\":\"var:preset|spacing|20\"} -->\n<div style=\"height:var(--wp--preset--spacing--20)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','','','inherit','closed','closed','','626-revision-v1','','','2026-02-08 19:59:56','2026-02-08 19:59:56','',626,'https://qmbqbrt0dq.wpdns.site/?p=631',0,'revision','',0),
